package com.masterclass.inventory.controller; import com.masterclass.inventory.dto.ReportDtos.*; import com.masterclass.inventory.service.ReportService; import lombok.RequiredArgsConstructor; import org.springframework.format.annotation.DateTimeFormat; import org.springframework.web.bind.annotation.*; import java.time.LocalDate; import java.util.*; @RestController @RequestMapping("/api/v1/reports") @RequiredArgsConstructor public class ReportController { private final ReportService service; @GetMapping("/inventory") public List<ProductInventoryReport> inventory(){return service.inventory();} @GetMapping("/inventory-value") public InventoryValueReport inventoryValue(){return service.inventoryValue();} @GetMapping("/low-stock") public List<ProductInventoryReport> lowStock(){return service.lowStock();} @GetMapping("/daily-sales") public DailySalesReport daily(@RequestParam @DateTimeFormat(iso=DateTimeFormat.ISO.DATE) LocalDate date){return service.daily(date);} }
